(()=>{const out=[];for(const kind of ['webgl','webgl2']){const g=new OffscreenCanvas(2,2).getContext(kind),t=g.createTexture();g.bindTexture(g.TEXTURE_2D,t);const r={kind,observations:[]};const upload=(type,value,format=g.RGBA)=>{try{g.texImage2D(g.TEXTURE_2D,0,format,1,1,0,g.RGBA,type,value);r.observations.push(['ok',g.getError()])}catch(e){r.observations.push([e.name,g.getError()])}};upload(g.FLOAT,new Float32Array(4));g.getExtension('OES_texture_float');upload(g.FLOAT,new Float32Array(4));upload(g.FLOAT,new Uint8Array(16));upload(g.UNSIGNED_BYTE,new Float32Array(4));const h=g.getExtension('OES_texture_half_float');upload(kind==='webgl'?h.HALF_FLOAT_OES:g.HALF_FLOAT,new Uint16Array(4),kind==='webgl'?g.RGBA:g.RGBA16F);upload(kind==='webgl'?h.HALF_FLOAT_OES:g.HALF_FLOAT,new Float32Array(4),kind==='webgl'?g.RGBA:g.RGBA16F);out.push(r)}return out})()
